"use strict";document.addEventListener("DOMContentLoaded",() =>{const form = document.getElementById("uploadForm");const input = document.getElementById("fileInput");const dropZone = document.getElementById("dropZone");const filesPreview = document.getElementById("filesPreview");const fileList = document.getElementById("fileList");const progressContainer = document.getElementById("progressContainer");const progressBar = document.getElementById("progressBar");const progressStatus = document.getElementById("progressStatus");const progressPercent = document.getElementById("progressPercent");const submitBtn = document.getElementById("submitBtn");const fileCountDisplay = document.getElementById("fileCount");const totalSizeDisplay = document.getElementById("totalSizeDisplay");const uploadedSizeDisplay = document.getElementById("uploadedSize");const totalSize = document.getElementById("totalSize");const loadingOverlay = document.getElementById("loadingOverlay");const ALLOWED_EXT = ".json";const showToast = (msg,type = "info") =>{window?.app?.showToast?.(msg,type) ?? console.log(`[${type}] ${msg}`);};const formatFileSize = (bytes) =>{if (!bytes) return "0 Bytes";const units = ["Bytes","KB","MB","GB"];const idx = Math.floor(Math.log(bytes) / Math.log(1024));return `${(bytes / Math.pow(1024,idx)).toFixed(2)}${units[idx]}`;};const calculateTotalSize = (fileList) => Array.from(fileList).reduce((total,f) => total + f.size,0);const filterValidFiles = (files) => Array.from(files).filter((file) => file.name.toLowerCase().endsWith(ALLOWED_EXT));const updateFileListInput = (files) =>{const dt = new DataTransfer();files.forEach((f) => dt.items.add(f));input.files = dt.files;};function updateFilePreview(){const files = Array.from(input.files);if (!files.length){filesPreview.classList.add("hidden");submitBtn.disabled = true;fileCountDisplay.textContent = "(0 files)";totalSizeDisplay.textContent = "0 KB";return;}filesPreview.classList.remove("hidden");submitBtn.disabled = false;const totalBytes = calculateTotalSize(files);fileCountDisplay.textContent = `(${files.length}${files.length === 1 ? "file":"files"})`;totalSizeDisplay.textContent = formatFileSize(totalBytes);fileList.innerHTML = "";files.forEach((file,index) =>{const card = document.createElement("div");card.className = "file-card bg-gray-50 p-3 rounded-lg flex items-center justify-between";const infoWrap = document.createElement("div");infoWrap.className = "flex items-center";const icon = document.createElement("span");icon.className = "material-icons text-gray-500 mr-3";icon.textContent = "insert_drive_file";const name = document.createElement("span");name.className = "text-sm font-medium text-gray-700 truncate max-w-xs";name.textContent = file.name;const size = document.createElement("span");size.className = "text-xs text-gray-500 ml-2";size.textContent = formatFileSize(file.size);const removeBtn = document.createElement("button");removeBtn.className = "text-gray-400 hover:text-red-500 transition";removeBtn.innerHTML = '<span class="material-icons">close</span>';removeBtn.addEventListener("click",(e) =>{e.stopPropagation();removeFile(index);});infoWrap.append(icon,name,size);card.append(infoWrap,removeBtn);fileList.appendChild(card);});}function removeFile(index){const files = Array.from(input.files);files.splice(index,1);updateFileListInput(files);updateFilePreview();}const activateDropZone = () => dropZone.classList.add("active");const deactivateDropZone = () => dropZone.classList.remove("active");dropZone.addEventListener("click",(e) =>{if (!e.target.closest("button")) input.click();});["dragenter","dragover"].forEach((evt) => dropZone.addEventListener(evt,(e) =>{e.preventDefault();activateDropZone();}) );["dragleave","drop"].forEach((evt) => dropZone.addEventListener(evt,(e) =>{e.preventDefault();deactivateDropZone();}) );dropZone.addEventListener("focus",activateDropZone);dropZone.addEventListener("blur",deactivateDropZone);dropZone.addEventListener("drop",(e) =>{const validFiles = filterValidFiles(e.dataTransfer.files);if (validFiles.length !== e.dataTransfer.files.length){showToast("Only JSON files are accepted","error");}if (validFiles.length){updateFileListInput(validFiles);updateFilePreview();}});input.addEventListener("change",() =>{const validFiles = filterValidFiles(input.files);if (validFiles.length !== input.files.length){showToast("Only JSON files are accepted","error");updateFileListInput(validFiles);}updateFilePreview();});form.addEventListener("submit",(e) =>{e.preventDefault();if (!input.files.length){showToast("Please select at least one JSON file","error");return;}const totalBytes = calculateTotalSize(input.files);const formData = new FormData(form);submitBtn.disabled = true;progressContainer.classList.remove("hidden");progressBar.style.width = "0%";progressPercent.textContent = "0%";progressStatus.textContent = "Preparing upload...";uploadedSizeDisplay.textContent = "0 KB";totalSize.textContent = formatFileSize(totalBytes);loadingOverlay?.classList.remove("hidden");const xhr = new XMLHttpRequest();xhr.upload.addEventListener("progress",(e) =>{if (!e.lengthComputable) return;const percent = Math.round((e.loaded / e.total) * 100);progressBar.style.width = `${percent}%`;progressPercent.textContent = `${percent}%`;uploadedSizeDisplay.textContent = formatFileSize(e.loaded);progressStatus.textContent = percent < 100 ? "Uploading...":"Processing files...";});xhr.addEventListener("load",() =>{loadingOverlay?.classList.add("hidden");const contentType = xhr.getResponseHeader("Content-Type") || "";if (!contentType.includes("application/json")){showToast("Unexpected server response","error");resetProgress();return;}let response;try{response = JSON.parse(xhr.responseText);}catch{showToast("Invalid server response","error");resetProgress();return;}if (response.success){progressBar.style.width = "100%";progressPercent.textContent = "100%";uploadedSizeDisplay.textContent = totalSize.textContent;progressStatus.textContent = "Upload complete";showToast("JSON files uploaded successfully!","success");setTimeout(() =>{const redirectUrl = response.redirect_url || `/view_diagram?root_name=${encodeURIComponent( input.files[0].name.replace(/\.[^/.]+$/,"") )}&diagramName=${encodeURIComponent( input.files[0].name.replace(/\.[^/.]+$/,"") )}.mmd`;window.location.href = redirectUrl;},1500);}else{showToast(response.message || "Upload failed","error");resetProgress();}});xhr.addEventListener("error",() =>{showToast("Network error occurred","error");resetProgress();});xhr.open("POST",form.action);xhr.setRequestHeader("X-Requested-With","XMLHttpRequest");xhr.send(formData);});function resetProgress(){progressContainer.classList.add("hidden");loadingOverlay?.classList.add("hidden");submitBtn.disabled = false;}form.addEventListener("reset",() =>{filesPreview.classList.add("hidden");resetProgress();progressBar.style.width = "0%";progressPercent.textContent = "0%";progressStatus.textContent = "Preparing upload...";uploadedSizeDisplay.textContent = "0 KB";totalSize.textContent = "0 KB";});});